<template><section class="customer-panel q-mt-lg"><div class="row justify-between items-center q-mb-md"><h2 class="section-heading q-mb-none">Account applications</h2><q-btn v-if="auth.isCustomer" color="primary" icon="add" label="Request an account" @click="open = true" /></div><p class="page-subtitle q-mb-md">{{ auth.isCustomer ? 'Apply for another account. An administrator will review your application.' : 'Administrators can approve or reject new account applications.' }} Approved accounts start with a zero balance.</p><q-banner v-if="error" class="bg-red-1 text-red-9">{{ error }}<q-btn flat label="Retry" @click="load" /></q-banner><q-table flat :rows="rows" :columns="columns" row-key="id" :loading="loading" :pagination="{ rowsPerPage: 5 }"><template #body-cell-action="p"><q-td :props="p"><template v-if="auth.isAdmin && p.row.status === 'PENDING'"><q-btn flat color="positive" label="Approve" :disable="busy" @click="review(p.row, 'APPROVED')" /><q-btn flat color="negative" label="Reject" :disable="busy" @click="review(p.row, 'REJECTED')" /></template></q-td></template></q-table><q-dialog v-model="open"><q-card style="width:420px"><q-form @submit="apply"><q-card-section><h2 class="section-heading">Request a Bembank account</h2><q-select v-model="typeId" filled :options="options" emit-value map-options label="Account type" :rules="[v => !!v || 'Choose an account type']" /><p v-if="!options.length" class="page-subtitle">No account types are available. Please contact bank staff.</p></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" v-close-popup /><q-btn color="primary" type="submit" label="Submit application" :loading="busy" :disable="!options.length" /></q-card-actions></q-form></q-card></q-dialog></section></template>
<script setup>
import { ref, computed, onMounted } from 'vue'
import { useQuasar } from 'quasar'
import { useAuthStore } from '@/stores/auth-store'
import api from '@/services/api'
const auth = useAuthStore(), $q = useQuasar(), rows = ref([]), options = ref([]), error = ref(''), loading = ref(false), busy = ref(false), open = ref(false), typeId = ref(null)
const columns = computed(() => [{ name: 'id', field: 'id', label: 'Application', align: 'left' }, ...(!auth.isCustomer ? [{ name: 'customer_id', field: 'customer_id', label: 'Customer ID', align: 'left' }] : []), { name: 'status', field: 'status', label: 'Status', align: 'left' }, { name: 'account_number', field: row => row.account_number || 'Awaiting review', label: 'Account number', align: 'left' }, ...(auth.isAdmin ? [{ name: 'action', field: 'id', label: 'Review', align: 'left' }] : [])])
async function load () { loading.value = true; error.value = ''; try { rows.value = (await api.get(auth.isCustomer ? '/customer/account-applications/' : '/account-applications/')).data; if (auth.isCustomer) options.value = (await api.get('/customer/account-options/')).data.map(t => ({ label: t.name, value: t.id })) } catch { error.value = 'Could not load account applications.' } finally { loading.value = false } }
const fail = e => $q.notify({ type: 'negative', message: typeof e.response?.data?.detail === 'string' ? e.response.data.detail : 'Could not process application.' })
async function apply () { busy.value = true; try { await api.post('/customer/account-applications/', { account_type_id: typeId.value }); open.value = false; typeId.value = null; await load(); $q.notify({ type: 'positive', message: 'Application submitted for review' }) } catch (e) { fail(e) } finally { busy.value = false } }
function review (row, status) { $q.dialog({ title: status === 'APPROVED' ? 'Approve account application?' : 'Reject account application?', message: `Application #${row.id} · Customer #${row.customer_id}`, cancel: true }).onOk(async () => { busy.value = true; try { await api.post(`/account-applications/${row.id}/review`, { status }); await load() } catch (e) { fail(e) } finally { busy.value = false } }) }
onMounted(load)
</script>
